class UpdateEmployeeRequest extends FormRequest { public function authorize(): bool{return true;} public function rules(): array { $route=$this->route('employee') ?? $this->route('id'); $employee=Employee::where('id',$route)->orWhere('employee_id',$route)->first(); $id=$employee?->id; return ['employee_id'=>['sometimes','required','string','max:50',Rule::unique('employees','employee_id')->ignore($id)],'hikvision_employee_no'=>['nullable','string','max:50',Rule::unique('employees','hikvision_employee_no')->ignore($id)],'nik'=>['sometimes','required','string','max:50',Rule::unique('employees','nik')->ignore($id)],'name'=>'sometimes|required|string|max:255','email'=>['nullable','email','max:255',Rule::unique('employees','email')->ignore($id)],'phone'=>'nullable|string|max:50','photo_path'=>'nullable|string|max:255','card_no'=>'nullable|string|max:50','department'=>'sometimes|required|string|max:100','role'=>'nullable|string|max:100','role_jabatan'=>'nullable|string|max:100','building_id'=>'nullable|exists:buildings,id','division_id'=>'nullable|exists:divisions,id','position_id'=>'nullable|exists:positions,id','employment_type'=>'nullable|string|max:50','employment_status'=>'nullable|in:ACTIVE,INACTIVE','hire_date'=>'nullable|date','supervisor_id'=>'nullable|exists:employees,id','fingerprint_enrolled'=>'nullable|boolean','card_enrolled'=>'nullable|boolean']; } }
